    pred: (pre, a, d, post) => {
      if (!(a in MOVES) || FINAL.includes(pre.status) || pre.status === 'none' || ![0, 1, 2].includes(d.task)) return true;
      return tasksOf(pre)[d.task] !== MOVES[a][0] || !same(pre, post);
    },
  },
  {
    name: 'cancel-cancels-exactly-in-flight',
    pred: (pre, a, d, post) => {
      if (a !== 'CANCEL' || same(pre, post)) return true;
      return tasksOf(pre).every((t, i) => tasksOf(post)[i] === (IN_FLIGHT.includes(t) ? 'cancelled' : t));
    },
  },
  {
    name: 'cancel-refused-only-when-nothing-in-flight-or-closed',
    pred: (pre, a, d, post) => {
      if (a !== 'CANCEL' || !same(pre, post)) return true;
      return pre.status === 'none' || FINAL.includes(pre.status) || !tasksOf(pre).some((t) => IN_FLIGHT.includes(t));
    },
  },
];

