  assert.equal((await h.taskFailed('r', 0)).ok, true);
  assert.equal((await h.run('r'))!.status, 'failed');
  assert.equal((await h.taskCompleted('r', 1)).ok, false);
  assert.equal((await h.cancel('r')).ok, false);
