'use strict';

// SAM v2 strict-profile spec of one run, derived from src/core.ts and
// src/host.impl.ts. status 'none' stands for "run id never started".

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { status: 'none', t0: 'none', t1: 'none', t2: 'none' };

const IN_FLIGHT = ['queued', 'running', 'evicted'];
const CLOSED = ['completed', 'cancelled'];
const TASK_KEYS = ['t0', 't1', 't2'];
const TASK_DOMAIN = [{ task: 0 }, { task: 1 }, { task: 2 }, { task: 3 }];
const TASK_SCHEMA = { task: { type: 'number' } };

function derive(a, b, c) {
  if (a === b && b === c) return a;
  if (a === 'failed' || b === 'failed' || c === 'failed') return 'failed';
  if (IN_FLIGHT.includes(a) || IN_FLIGHT.includes(b) || IN_FLIGHT.includes(c)) return 'running';
  return 'cancelled';
}

const taskMove = (from, to) => (model) => (proposal, { reject, next }) => {
  if (model.status === 'none') return reject('no-such-run');
  if (CLOSED.includes(model.status)) return reject('run-closed');
  const task = proposal.task;
  if (task !== 0 && task !== 1 && task !== 2) return reject('bad-task');
  const key = TASK_KEYS[task];
  if (model[key] !== from) return reject('illegal-move');
  const tasks = TASK_KEYS.map((k) => (k === key ? to : model[k]));
  next.t0 = tasks[0];
  next.t1 = tasks[1];
  next.t2 = tasks[2];
  next.status = derive(tasks[0], tasks[1], tasks[2]);
};

const taskAction = () => ({ action: (data = {}) => ({ ...data }), schema: { ...TASK_SCHEMA }, domain: TASK_DOMAIN.map((d) => ({ ...d })) });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      t0: { type: 'string' },
      t1: { type: 'string' },
      t2: { type: 'string' },
    },
    actions: {
      START: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      TASK_STARTED: taskAction(),
      TASK_COMPLETED: taskAction(),
      TASK_FAILED: taskAction(),
      TASK_EVICTED: taskAction(),
      TASK_REQUEUED: taskAction(),
      TASK_RETRIED: taskAction(),
      CANCEL: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
    },
    acceptors: {
      START: (model) => (proposal, { reject, next }) => {
        if (model.status !== 'none') return reject('run-exists');
        next.status = 'queued';
        next.t0 = 'queued';
        next.t1 = 'queued';
        next.t2 = 'queued';
      },
      TASK_STARTED: taskMove('queued', 'running'),
      TASK_COMPLETED: taskMove('running', 'completed'),
      TASK_FAILED: taskMove('running', 'failed'),
      TASK_EVICTED: taskMove('running', 'evicted'),
      TASK_REQUEUED: taskMove('evicted', 'queued'),
      TASK_RETRIED: taskMove('failed', 'queued'),
      CANCEL: (model) => (proposal, { reject, next }) => {
        if (model.status === 'none') return reject('no-such-run');
        if (CLOSED.includes(model.status)) return reject('run-closed');
        const tasks = TASK_KEYS.map((k) => (IN_FLIGHT.includes(model[k]) ? 'cancelled' : model[k]));
        if (tasks.every((s, i) => s === model[TASK_KEYS[i]])) return reject('nothing-in-flight');
        next.t0 = tasks[0];
        next.t1 = tasks[1];
        next.t2 = tasks[2];
        next.status = derive(tasks[0], tasks[1], tasks[2]);
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  START: (data = {}) => intents.START(data),
  TASK_STARTED: (data = {}) => intents.TASK_STARTED(data),
  TASK_COMPLETED: (data = {}) => intents.TASK_COMPLETED(data),
  TASK_FAILED: (data = {}) => intents.TASK_FAILED(data),
  TASK_EVICTED: (data = {}) => intents.TASK_EVICTED(data),
  TASK_REQUEUED: (data = {}) => intents.TASK_REQUEUED(data),
  TASK_RETRIED: (data = {}) => intents.TASK_RETRIED(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
};

module.exports = { instance, init, actions, getState, setState };

