// Rules the brief requires, written from the brief (not from the code).

const IN_FLIGHT = ['queued', 'running', 'evicted'];
// Run statuses that refuse every command (change 1: a failed run no longer does).
const CLOSED = ['completed', 'cancelled'];
const tasksOf = (s) => [s.t0, s.t1, s.t2];
const same = (a, b) => a.status === b.status && a.t0 === b.t0 && a.t1 === b.t1 && a.t2 === b.t2;
const MOVES = {
  TASK_STARTED: ['queued', 'running'],
  TASK_COMPLETED: ['running', 'completed'],
  TASK_FAILED: ['running', 'failed'],
  TASK_EVICTED: ['running', 'evicted'],
  TASK_REQUEUED: ['evicted', 'queued'],
  TASK_RETRIED: ['failed', 'queued'],
};

export const stateInvariants = [
  { name: 'unstarted-run-has-no-tasks', pred: (s) => s.status !== 'none' || tasksOf(s).every((t) => t === 'none') },
  { name: 'started-run-has-real-tasks', pred: (s) => s.status === 'none' || tasksOf(s).every((t) => t !== 'none') },
  { name: 'all-same-means-that-status', pred: (s) => !(s.t0 === s.t1 && s.t1 === s.t2) || s.status === s.t0 },
  { name: 'completed-only-when-all-completed', pred: (s) => s.status !== 'completed' || tasksOf(s).every((t) => t === 'completed') },
  { name: 'failed-whenever-a-task-failed', pred: (s) => !tasksOf(s).includes('failed') || s.status === 'failed' },
  { name: 'never-completed-or-cancelled-with-task-in-flight', pred: (s) => !['completed', 'cancelled'].includes(s.status) || !tasksOf(s).some((t) => IN_FLIGHT.includes(t)) },
  { name: 'running-means-mixed-in-flight-no-failure', pred: (s) => s.status !== 'running' || (tasksOf(s).some((t) => IN_FLIGHT.includes(t)) && !tasksOf(s).includes('failed') && !(s.t0 === s.t1 && s.t1 === s.t2)) || (s.t0 === 'running' && s.t1 === 'running' && s.t2 === 'running') },
  { name: 'queued-or-evicted-status-only-when-uniform', pred: (s) => !['queued', 'evicted'].includes(s.status) || (s.t0 === s.t1 && s.t1 === s.t2) },
];

export const transitionInvariants = [
  { name: 'failed-run-is-not-closed', pred: (pre, a, d, post) => !(pre.status === 'failed' && a === 'TASK_RETRIED' && [0, 1, 2].includes(d.task) && tasksOf(pre)[d.task] === 'failed') || tasksOf(post)[d.task] === 'queued' },
  { name: 'closed-run-refuses-everything', pred: (pre, a, d, post) => !CLOSED.includes(pre.status) || same(pre, post) },
  { name: 'unstarted-run-only-accepts-start', pred: (pre, a, d, post) => pre.status !== 'none' || a === 'START' || same(pre, post) },
  { name: 'start-refused-when-exists', pred: (pre, a, d, post) => a !== 'START' || pre.status === 'none' || same(pre, post) },
  { name: 'start-creates-queued', pred: (pre, a, d, post) => a !== 'START' || pre.status !== 'none' || (post.status === 'queued' && tasksOf(post).every((t) => t === 'queued')) },
  { name: 'bad-task-refused', pred: (pre, a, d, post) => !(a in MOVES) || [0, 1, 2].includes(d.task) || same(pre, post) },
  {
    name: 'task-report-follows-moves',
    pred: (pre, a, d, post) => {
      if (!(a in MOVES) || same(pre, post)) return true;
      const [from, to] = MOVES[a];
      const pt = tasksOf(pre), qt = tasksOf(post);
