4	import type { Status } from '../host.ts';
5	
6	export type Tasks = readonly [Status, Status, Status];
7	
8	export interface RunState {
9	  status: Status;
10	  tasks: Tasks;
11	}
12	
13	export type TaskEvent = 'started' | 'completed' | 'failed' | 'evicted' | 'requeued' | 'retried';
14	
15	export type StepResult = { ok: true; state: RunState } | { ok: false; reason: string };
16	
17	const IN_FLIGHT: ReadonlySet<Status> = new Set<Status>(['queued', 'running', 'evicted']);
18	/** Run statuses that refuse every command; a failed run can still retry. */
19	const CLOSED_RUN: ReadonlySet<Status> = new Set<Status>(['completed', 'cancelled']);
20	
21	/** Each task report: the status it requires, and the status it moves to. */
22	const MOVES: Record<TaskEvent, { from: Status; to: Status }> = {
23	  started: { from: 'queued', to: 'running' },
24	  completed: { from: 'running', to: 'completed' },
25	  failed: { from: 'running', to: 'failed' },
26	  evicted: { from: 'running', to: 'evicted' },
27	  requeued: { from: 'evicted', to: 'queued' },
28	  retried: { from: 'failed', to: 'queued' },
29	};
30	
31	export function isInFlight(s: Status): boolean {
32	  return IN_FLIGHT.has(s);
33	}
34	
35	export function deriveStatus(tasks: Tasks): Status {
36	  const [a, b, c] = tasks;
37	  if (a === b && b === c) return a;
38	  if (tasks.includes('failed')) return 'failed';
39	  if (tasks.some(isInFlight)) return 'running';
40	  return 'cancelled';
41	}
42	
43	export function initialRun(): RunState {
44	  return { status: 'queued', tasks: ['queued', 'queued', 'queued'] };
45	}
46	
47	export function isClosed(state: RunState): boolean {
48	  return CLOSED_RUN.has(state.status);
49	}
50	
51	function settle(tasks: Tasks): RunState {
52	  return { status: deriveStatus(tasks), tasks };
53	}
54	
55	export function applyTaskEvent(state: RunState, event: TaskEvent, task: number): StepResult {
56	  if (isClosed(state)) return { ok: false, reason: `run is ${state.status}` };
57	  if (!Number.isInteger(task) || task < 0 || task > 2) {
58	    return { ok: false, reason: `no task ${String(task)}` };
59	  }
60	  const move = MOVES[event];
61	  const current = state.tasks[task];
62	  if (current !== move.from) {
63	    return { ok: false, reason: `task ${task} is ${current}, not ${move.from}` };
64	  }
65	  const tasks = state.tasks.map((s, i) => (i === task ? move.to : s)) as unknown as Tasks;
66	  return { ok: true, state: settle(tasks) };
67	}
68	
69	export function applyCancelTask(state: RunState, task: number): StepResult {
70	  if (isClosed(state)) return { ok: false, reason: `run is ${state.status}` };
71	  if (!Number.isInteger(task) || task < 0 || task > 2) {
72	    return { ok: false, reason: `no task ${String(task)}` };
73	  }
74	  const current = state.tasks[task];
75	  if (!isInFlight(current)) return { ok: false, reason: `task ${task} is ${current}` };

