import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('start creates a queued run; duplicate refused; unknown is null', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.deepEqual(await h.start('a'), { ok: true });
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  assert.equal((await h.start('a')).ok, false);
});

test('commands on unknown runs are refused', async () => {
  const h = await createHost();
  assert.equal((await h.taskStarted('x', 0)).ok, false);
  assert.equal((await h.cancel('x')).ok, false);
  assert.equal(await h.run('x'), null);
});

test('happy path to completed, then everything refused', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) assert.equal((await h.taskStarted('r', t)).ok, true);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskCompleted('r', 0);
  await h.taskCompleted('r', 1);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskCompleted('r', 2);
  assert.equal((await h.run('r'))!.status, 'completed');
  assert.equal((await h.cancel('r')).ok, false);
  assert.equal((await h.start('r')).ok, false);
});

test('mixed statuses: one started -> running', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 1);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'queued', task1: 'running', task2: 'queued' });
});

test('failure fails the run but the run still accepts commands', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskStarted('r', 1);
  assert.equal((await h.taskFailed('r', 0)).ok, true);
  assert.equal((await h.run('r'))!.status, 'failed');
  assert.equal((await h.taskCompleted('r', 1)).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'failed', task1: 'completed', task2: 'queued' });
});

test('retry a failed task back to completion', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) await h.taskStarted('r', t);
  await h.taskCompleted('r', 1);
  await h.taskCompleted('r', 2);
  await h.taskFailed('r', 0);
  assert.equal((await h.run('r'))!.status, 'failed');
  assert.deepEqual(await h.taskRetried('r', 0), { ok: true });
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'queued', task1: 'completed', task2: 'completed' });
  assert.equal((await h.taskRetried('r', 0)).ok, false);
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
  assert.equal((await h.run('r'))!.status, 'completed');
  assert.equal((await h.taskRetried('r', 0)).ok, false);
});

test('retry refused unless the task failed, or with a bad task number', async () => {
  const h = await createHost();
  assert.equal((await h.taskRetried('r', 0)).ok, false);
  await h.start('r');
  assert.equal((await h.taskRetried('r', 0)).ok, false);
  await h.taskStarted('r', 0);
  assert.equal((await h.taskRetried('r', 0)).ok, false);
  await h.taskFailed('r', 0);
  assert.equal((await h.taskRetried('r', 3)).ok, false);
  assert.equal((await h.taskRetried('r', -1)).ok, false);
  assert.equal((await h.run('r'))!.task0, 'failed');
});

test('all three failed: run failed, cancel refused, retries reopen it', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) await h.taskStarted('r', t);
  for (const t of [0, 1, 2]) await h.taskFailed('r', t);
  assert.equal((await h.run('r'))!.status, 'failed');
  assert.equal((await h.cancel('r')).ok, false);
  for (const t of [0, 1, 2]) assert.equal((await h.taskRetried('r', t)).ok, true);
  assert.equal((await h.run('r'))!.status, 'queued');
});

test('cancel on a failed run cancels in-flight tasks and stays failed; retry then cancel', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskFailed('r', 0);
  assert.deepEqual(await h.cancel('r'), { ok: true });
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'failed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.cancel('r')).ok, false);
  await h.taskRetried('r', 0);
  assert.equal((await h.run('r'))!.status, 'running');
  assert.deepEqual(await h.cancel('r'), { ok: true });
  assert.equal((await h.run('r'))!.status, 'cancelled');
  assert.equal((await h.taskRetried('r', 0)).ok, false);
});

test('eviction and requeue', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) await h.taskStarted('r', t);
  for (const t of [0, 1, 2]) await h.taskEvicted('r', t);
  assert.equal((await h.run('r'))!.status, 'evicted');
  assert.equal((await h.taskRequeued('r', 0)).ok, true);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskRequeued('r', 1);
  await h.taskRequeued('r', 2);
  assert.equal((await h.run('r'))!.status, 'queued');
});

test('completed + evicted is running, never completed', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) await h.taskStarted('r', t);
  await h.taskCompleted('r', 0);
  await h.taskCompleted('r', 1);
  await h.taskEvicted('r', 2);
  assert.equal((await h.run('r'))!.status, 'running');
});

test('cancel cancels in-flight tasks; completed+cancelled is cancelled', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
  await h.taskStarted('r', 1);
  await h.taskEvicted('r', 1);
  assert.deepEqual(await h.cancel('r'), { ok: true });
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.cancel('r')).ok, false);
});

test('illegal moves and bad task numbers refused without change', async () => {
  const h = await createHost();
  await h.start('r');
  const before = await h.run('r');
  assert.equal((await h.taskCompleted('r', 0)).ok, false);
  assert.equal((await h.taskEvicted('r', 0)).ok, false);
  assert.equal((await h.taskRequeued('r', 0)).ok, false);
  assert.equal((await h.taskFailed('r', 0)).ok, false);
  for (const t of [3, -1, 1.5, NaN]) assert.equal((await h.taskStarted('r', t)).ok, false);
  assert.deepEqual(await h.run('r'), before);
  await h.taskStarted('r', 0);
  assert.equal((await h.taskStarted('r', 0)).ok, false);
});

test('cancelTask cancels one in-flight task of any kind', async () => {
  const h = await createHost();
  await h.start('r');
  assert.deepEqual(await h.cancelTask('r', 0), { ok: true });
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'cancelled', task1: 'queued', task2: 'queued' });
  await h.taskStarted('r', 1);
  assert.deepEqual(await h.cancelTask('r', 1), { ok: true });
  await h.taskStarted('r', 2);
  await h.taskEvicted('r', 2);
  assert.equal((await h.run('r'))!.status, 'running');
  assert.deepEqual(await h.cancelTask('r', 2), { ok: true });
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.cancelTask('r', 0)).ok, false);
});

test('cancelTask refused for final tasks, bad numbers, unknown runs', async () => {
  const h = await createHost();
  assert.equal((await h.cancelTask('r', 0)).ok, false);
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
  await h.taskStarted('r', 1);
  await h.taskFailed('r', 1);
  assert.equal((await h.cancelTask('r', 0)).ok, false);
  assert.equal((await h.cancelTask('r', 1)).ok, false);
  assert.equal((await h.cancelTask('r', 3)).ok, false);
  assert.equal((await h.cancelTask('r', -1)).ok, false);
  assert.deepEqual(await h.cancelTask('r', 2), { ok: true });
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'completed', task1: 'failed', task2: 'cancelled' });
  assert.equal((await h.cancelTask('r', 2)).ok, false);
});

test('cancelTask with the rest completed derives cancelled', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1]) { await h.taskStarted('r', t); await h.taskCompleted('r', t); }
  assert.deepEqual(await h.cancelTask('r', 2), { ok: true });
  assert.equal((await h.run('r'))!.status, 'cancelled');
  assert.equal((await h.taskStarted('r', 2)).ok, false);
});

test('runs are independent and systems are fresh', async () => {
  const h = await createHost();
  await h.start('a');
  await h.start('b');
  await h.taskStarted('a', 0);
  assert.equal((await h.run('b'))!.status, 'queued');
  const h2 = await createHost();
  assert.equal(await h2.run('a'), null);
});

