// Drive the real host and record one NDJSON window per command:
//   node spec/capture.ts  -> spec/traces/*.ndjson
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import createHost from '../src/host.impl.ts';

type Cmd = [action: string, task?: number];

const RUN = 'r';
const scenarios: Record<string, Cmd[]> = {
  happy: [['START'], ['TASK_STARTED', 0], ['TASK_STARTED', 1], ['TASK_STARTED', 2], ['TASK_COMPLETED', 0], ['TASK_COMPLETED', 1], ['TASK_COMPLETED', 2], ['CANCEL'], ['TASK_STARTED', 0], ['START']],
  unstarted: [['TASK_STARTED', 0], ['CANCEL'], ['START'], ['START']],
  failure: [['START'], ['TASK_STARTED', 0], ['TASK_STARTED', 1], ['TASK_FAILED', 1], ['TASK_COMPLETED', 0], ['CANCEL'], ['TASK_EVICTED', 0]],
  evict: [['START'], ['TASK_STARTED', 0], ['TASK_STARTED', 1], ['TASK_STARTED', 2], ['TASK_EVICTED', 0], ['TASK_EVICTED', 1], ['TASK_EVICTED', 2], ['TASK_REQUEUED', 0], ['TASK_REQUEUED', 1], ['TASK_REQUEUED', 2], ['TASK_STARTED', 2], ['TASK_COMPLETED', 2], ['TASK_STARTED', 0], ['TASK_EVICTED', 0], ['CANCEL'], ['CANCEL']],
  illegal: [['START'], ['TASK_COMPLETED', 0], ['TASK_EVICTED', 1], ['TASK_REQUEUED', 2], ['TASK_FAILED', 0], ['TASK_STARTED', 3], ['TASK_STARTED', 0], ['TASK_STARTED', 0], ['TASK_REQUEUED', 0], ['TASK_COMPLETED', 3], ['TASK_COMPLETED', 0], ['TASK_COMPLETED', 0], ['TASK_STARTED', 1], ['TASK_FAILED', 1]],
  retry: [['START'], ['TASK_RETRIED', 0], ['TASK_STARTED', 0], ['TASK_STARTED', 1], ['TASK_STARTED', 2], ['TASK_RETRIED', 0], ['TASK_FAILED', 0], ['TASK_RETRIED', 3], ['TASK_COMPLETED', 1], ['TASK_FAILED', 2], ['CANCEL'], ['TASK_RETRIED', 0], ['TASK_RETRIED', 2], ['TASK_STARTED', 0], ['TASK_STARTED', 2], ['TASK_COMPLETED', 0], ['TASK_COMPLETED', 2], ['TASK_RETRIED', 0]],
  failedCancel: [['START'], ['TASK_STARTED', 0], ['TASK_FAILED', 0], ['CANCEL'], ['CANCEL'], ['TASK_RETRIED', 0], ['CANCEL'], ['TASK_RETRIED', 0]],
  cancelTask: [['CANCEL_TASK', 0], ['START'], ['CANCEL_TASK', 0], ['CANCEL_TASK', 0], ['CANCEL_TASK', 3], ['TASK_STARTED', 1], ['TASK_EVICTED', 1], ['CANCEL_TASK', 1], ['TASK_STARTED', 2], ['TASK_FAILED', 2], ['CANCEL_TASK', 2], ['TASK_RETRIED', 2], ['TASK_STARTED', 2], ['CANCEL_TASK', 2], ['CANCEL_TASK', 2]],
  cancelTaskRest: [['START'], ['TASK_STARTED', 0], ['TASK_COMPLETED', 0], ['TASK_STARTED', 1], ['TASK_COMPLETED', 1], ['CANCEL_TASK', 2], ['TASK_STARTED', 2]],
  cancelMixed: [['START'], ['TASK_STARTED', 0], ['TASK_COMPLETED', 0], ['TASK_STARTED', 1], ['CANCEL'], ['TASK_STARTED', 2], ['CANCEL']],
};

// deterministic pseudo-random walks for breadth
let seed = 7;
const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
const ACTIONS = ['TASK_STARTED', 'TASK_COMPLETED', 'TASK_FAILED', 'TASK_EVICTED', 'TASK_REQUEUED', 'TASK_RETRIED', 'CANCEL_TASK', 'CANCEL'];
for (let w = 0; w < 20; w++) {
  const cmds: Cmd[] = [['START']];
  for (let i = 0; i < 25; i++) {
    const a = ACTIONS[rnd(ACTIONS.length)];
    cmds.push(a === 'CANCEL' ? (rnd(4) === 0 ? ['CANCEL'] : ['TASK_STARTED', rnd(3)]) : [a, rnd(4)]);
  }
  scenarios[`walk${w}`] = cmds;
}

async function snapshot(h: Awaited<ReturnType<typeof createHost>>) {
  const v = await h.run(RUN);
  return v ? { status: v.status, t0: v.task0, t1: v.task1, t2: v.task2 } : { status: 'none', t0: 'none', t1: 'none', t2: 'none' };
}

rmSync('spec/traces', { recursive: true, force: true });
mkdirSync('spec/traces', { recursive: true });
for (const [name, cmds] of Object.entries(scenarios)) {
  const h = await createHost();
  const lines: string[] = [];
  for (const [action, task] of cmds) {
    const pre = await snapshot(h);
    switch (action) {
      case 'START': await h.start(RUN); break;
      case 'CANCEL': await h.cancel(RUN); break;
      case 'TASK_STARTED': await h.taskStarted(RUN, task!); break;
      case 'TASK_COMPLETED': await h.taskCompleted(RUN, task!); break;
      case 'TASK_FAILED': await h.taskFailed(RUN, task!); break;
      case 'TASK_EVICTED': await h.taskEvicted(RUN, task!); break;
      case 'TASK_REQUEUED': await h.taskRequeued(RUN, task!); break;
      case 'TASK_RETRIED': await h.taskRetried(RUN, task!); break;
      case 'CANCEL_TASK': await h.cancelTask(RUN, task!); break;
    }
    const post = await snapshot(h);
    lines.push(JSON.stringify({ pre, action, data: task === undefined ? {} : { task }, post }));
  }
  writeFileSync(`spec/traces/${name}.ndjson`, lines.join('\n') + '\n');
}
console.log(`wrote ${Object.keys(scenarios).length} traces`);

